import {
	View,
	Text,
	useWindowDimensions,
	TouchableOpacity,
	Linking
} from 'react-native'
import { defineStyles } from '@/utils/defineStyles'
import { colors, Theme, useTheme } from '@/theme'
import Animated, {
	interpolate,
	SharedValue,
	useAnimatedStyle,
	useSharedValue
} from 'react-native-reanimated'
import Carousel from 'react-native-reanimated-carousel'
import {
	purchaseCreditsEmitter,
	PurchaseCreditsEvents,
	upgradePlanEmitter,
	UpgradePlanEvents
} from '@/utils/emitter'
import { useCurrentOrganization } from '@/utils/hooks'
import { isSubscribed } from '@/utils'

type ProjectCreationBlockerItem = {
	id: number
	title: string
	description: string
	actionButtonText: string
	actionButtonPress: () => Promise<void> | void
}

const HasReachedChatCreditsLimitSubscriptionBlocker: ProjectCreationBlockerItem =
	{
		id: 1,
		title: 'Get a higher plan for more generations',
		description: 'Upgrade your plan to get more generations.',
		actionButtonText: 'Upgrade plan',
		actionButtonPress: () => {
			upgradePlanEmitter.emit(UpgradePlanEvents.OPEN_MODAL)
		}
	}

const HasReachedChatCreditsLimitCreditsBlocker: ProjectCreationBlockerItem = {
	id: 1,
	title: 'Purchase more credits',
	description: 'Purchase more credits to continue using the app.',
	actionButtonText: 'Purchase credits',
	actionButtonPress: () => {
		purchaseCreditsEmitter.emit(PurchaseCreditsEvents.OPEN_MODAL)
	}
}

const HasSpeechPermissionBlocker: ProjectCreationBlockerItem = {
	id: 2,
	title: 'Enable microphone access',
	description:
		"You'll need to enable microphone access in system settings to prompt.",
	actionButtonText: 'Settings',
	actionButtonPress: async () => {
		Linking.openSettings()
	}
}

const Dot = ({
	index,
	progress
}: {
	index: number
	progress: SharedValue<number>
}) => {
	const { theme } = useTheme()

	const animatedDotStyle = useAnimatedStyle(() => {
		const distanceFromProgress = Math.abs(progress.get() - index)

		const opacity = interpolate(distanceFromProgress, [0, 1], [1, 0.2])

		return { opacity }
	})

	return (
		<Animated.View
			style={[
				{
					width: 8,
					height: 8,
					borderRadius: 999,
					backgroundColor: colors[theme].gray[900]
				},
				animatedDotStyle
			]}
		/>
	)
}

export const ProjectCreationBlocker = ({
	hasReachedChatCreditsLimit,
	hasSpeechPermission
}: {
	hasReachedChatCreditsLimit: boolean
	hasSpeechPermission: boolean
}) => {
	const { currentOrganization } = useCurrentOrganization()
	const { width } = useWindowDimensions()
	const { theme } = useTheme()

	const progress = useSharedValue(0)

	if (!currentOrganization) return null

	const visibleBlockers = []

	if (hasReachedChatCreditsLimit) {
		if (isSubscribed({ plan: currentOrganization.plan })) {
			visibleBlockers.push(HasReachedChatCreditsLimitCreditsBlocker)
		} else {
			visibleBlockers.push(HasReachedChatCreditsLimitSubscriptionBlocker)
		}
	}
	if (!hasSpeechPermission) {
		visibleBlockers.push(HasSpeechPermissionBlocker)
	}

	if (visibleBlockers.length === 0) return null

	return (
		<>
			<Carousel
				enabled={visibleBlockers.length > 1}
				width={width - 40} // padding is 20
				data={visibleBlockers}
				pagingEnabled={true}
				loop={false}
				onProgressChange={(_, absoluteProgress) => {
					progress.set(absoluteProgress)
				}}
				renderItem={({ item }) => (
					<View style={styles.container}>
						<View style={styles.textContainer}>
							<Text style={styles.title(theme)}>{item.title}</Text>
							<Text style={styles.description(theme)}>{item.description}</Text>
						</View>
						<TouchableOpacity
							style={styles.actionButton(theme)}
							onPress={item.actionButtonPress}
						>
							<Text style={styles.actionButtonText(theme)}>
								{item.actionButtonText}
							</Text>
						</TouchableOpacity>
					</View>
				)}
			/>

			{visibleBlockers.length > 1 && (
				<View style={styles.dotsContainer}>
					{visibleBlockers.map((_, index) => (
						<Dot key={index} index={index} progress={progress} />
					))}
				</View>
			)}
		</>
	)
}

const styles = defineStyles({
	container: {
		gap: 20,
		paddingHorizontal: 20
	},
	textContainer: {
		gap: 4
	},
	title: (theme: Theme) => ({
		fontSize: 16,
		fontWeight: '500',
		color: colors[theme].gray[900]
	}),
	description: (theme: Theme) => ({
		fontSize: 16,
		fontWeight: '500',
		color: colors[theme].gray[400],
		lineHeight: 22
	}),
	actionButton: (theme: Theme) => ({
		alignSelf: 'flex-start',
		backgroundColor: colors[theme].gray[900],
		flexDirection: 'row',
		alignItems: 'center',
		gap: 8,
		paddingHorizontal: 8,
		paddingVertical: 8,
		borderRadius: 10
	}),
	actionButtonText: (theme: Theme) => ({
		fontSize: 16,
		fontWeight: '500',
		color: colors[theme].background
	}),
	dotsContainer: {
		flexDirection: 'row',
		gap: 8,
		position: 'absolute',
		alignSelf: 'center',
		bottom: 20
	}
})
